      fearless: P({}),
      fighter: P({}),
      hammer: P({ splashRadius: 1, splashScale: 0.5, splashOthersOnly: true }),
      instructor: P({ dmgMul: (battle, unit, target2) => target2.blockedBy === unit ? 1 : unit.profile.unblockedScale ?? 1.2 }),
