      // PRTS 溅射半径一览 特殊: 格雷伊 1.0 (the branch's 1.1 otherwise)
      splashcaster: (tb, def) => (def.charId ?? def.raw?.charId) === "char_253_greyy" ? { splashRadius: 1 } : {},
      hunter: (tb) => ({ ammoMax: num4(tb.value, 8), ammoScale: num4(tb.atk_scale, 1.2) }),
      reaperrange: (tb, def) => ({ frontScale: num4(tb.atk_scale, 1.5), frontGrid: def.raw?.trait?.rangeGrid ?? null }),
