        if (f) o.falloff = +f[1] / 100;
        if (tb["attack@chain.max_target"] != null) o.count = num4(tb["attack@chain.max_target"], o.count);
        if (tb["attack@chain.atk_scale"] != null) o.falloff = 1 - num4(tb["attack@chain.atk_scale"], 1 - o.falloff);
